package br.com.gustavo.nossotempo;
import android.app.*;import android.content.*;import android.os.Build;import java.time.*;
final class AnniversaryScheduler {static void scheduleAll(Context c){ZonedDateTime now=ZonedDateTime.now(RelationshipTime.ZONE),next=now.withDayOfMonth(12).withHour(16).withMinute(43).withSecond(0).withNano(0);if(!next.isAfter(now))next=next.plusMonths(1);set(c,next.minusDays(10),"10",101);set(c,next.minusDays(5),"5",102);set(c,next,"day",103);}private static void set(Context c,ZonedDateTime w,String type,int id){if(!w.isAfter(ZonedDateTime.now(RelationshipTime.ZONE)))return;AlarmManager a=c.getSystemService(AlarmManager.class);PendingIntent p=PendingIntent.getBroadcast(c,id,new Intent(c,AnniversaryReceiver.class).putExtra("type",type),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT<31||a.canScheduleExactAlarms())a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,w.toInstant().toEpochMilli(),p);else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,w.toInstant().toEpochMilli(),p);}}
